import json,os,pathlib,hashlib,base64,urllib.request,tempfile,subprocess,shutil,sys
ROOT=pathlib.Path('/home/appontrack/public_html/ayo')
BACK=pathlib.Path('/home/appontrack/.ayo-repair-chat-audio-v10-20261105')
D=json.loads(sys.argv[1]);allowed={'.htaccess','api.php','app.js','index.php','style.css'}
if set(D)!=allowed or not ROOT.is_dir() or ROOT.is_symlink() or BACK.exists():raise RuntimeError('Unsafe AYO deployment state')
cfg=json.loads(pathlib.Path('/home/appontrack/ontrack-voice-link/config.json').read_text())
headers={'Authorization':'Bearer '+cfg['token'],'Accept':'application/vnd.github+json','User-Agent':'OnTrack-AYO-Scoped-Publisher'}
def git_sha(b):return hashlib.sha1(b'blob '+str(len(b)).encode()+b'\0'+b).hexdigest()
artifacts={}
for name,sha in D.items():
 u='https://api.github.com/repos/OnTrack-Development/OnTrack-voice/contents/ayo/'+name+'?ref=feat/ayo-php-host-demo-20261105'
 with urllib.request.urlopen(urllib.request.Request(u,headers=headers),timeout=8) as r: obj=json.load(r)
 if obj.get('sha')!=sha:raise RuntimeError('Remote revision changed '+name)
 raw=base64.b64decode(obj['content'])
 if git_sha(raw)!=sha:raise RuntimeError('Blob mismatch '+name)
 artifacts[name]=raw
php=shutil.which('php') or '/usr/local/bin/php'
with tempfile.TemporaryDirectory(prefix='.ayo-lint-',dir='/home/appontrack') as temp:
 t=pathlib.Path(temp)
 for name,raw in artifacts.items():(t/name).write_bytes(raw)
 for name in ['api.php','index.php']:
  v=subprocess.run([php,'-l',str(t/name)],capture_output=True,text=True,timeout=7)
  if v.returncode:raise RuntimeError('PHP lint failed '+name+' '+v.stderr[:200])
 BACK.mkdir(mode=0o700)
 previous=set()
 for name in allowed:
  f=ROOT/name
  if f.is_symlink():raise RuntimeError('Symlink refused '+name)
  if f.is_file():(BACK/name).write_bytes(f.read_bytes());previous.add(name)
 changed=[]
 try:
  for name,raw in artifacts.items():
   target=ROOT/name;tmp=ROOT/(name+'.ayo-repair-temp')
   fd=os.open(tmp,os.O_WRONLY|os.O_CREAT|os.O_EXCL,0o644)
   with os.fdopen(fd,'wb') as out:out.write(raw)
   os.chmod(tmp,0o644);os.replace(tmp,target)
   changed.append(name)
 except:
  for name in changed:
   f=ROOT/name
   if name in previous:f.write_bytes((BACK/name).read_bytes());f.chmod(0o644)
   else:f.unlink(missing_ok=True)
  raise
print(json.dumps({'status':'deployed','scope':'ayo only','files':sorted(changed),'php_lint':'ok','sha_integrity':'ok','backup':'outside public_html','microphone_htaccess':'installed'}))
